SELECT 1 FROM EMP AS EMP1 INNER JOIN EMP AS EMP2 ON EMP1.DEPTNO = EMP2.DEPTNO
SELECT * FROM (VALUES (NULL, NULL, NULL)) AS t(X, B, A) WHERE 1 = 0
